scripts.救蔷薇.txt:
StopMusic();
Say("杨影枫：咦？前面好像是飞龙堡的弟子。",2);
Say("杨影枫：哼！他们又在干什么鬼勾当。",2);
SetMapTrap(1,"");
SetMapTrap(2,"");
SetPlayerDir(1);
MoveScreen(1,70,2);
PlaySound("mpc241.wav");
Say("蒙面人头目：就这么带这个小妞儿回去交差是不是太可惜了？我们兄弟冒了多大的危险才把她抓来，不如让我们先享受一下吧。",69);
Say("其他蒙面人齐声赞同");
Say("蒙面人甲：嘿嘿……大哥说的对，我也想尝一尝这武林盟主的女儿到底是什么滋味。");
Say("蒙面人乙：这里人烟稀少，正好行事，大哥先来吧，我们给你放风。");
Say("蒙面人丙：这个小妞儿挺不容易对付的，大哥你可要小心呀。");
Say("蒙面人头目：哈哈……不用担心，我就喜欢这种类型的。",69);
PlayerRunTo(49,33);
Say("杨影枫：住手！",6);
Watch("杨影枫","ALLNPC",1);
Say("蒙面人头目：你是谁？竟敢管我们的闲事，活的不耐烦了？",69);
Say("蒙面人甲：大哥，别跟这小子废话，宰了他！");
Say("蒙面人乙：大家一齐上，别让这小子跑了。");
GetNpcCount(1,1);
EnableNpcAI();
PlayMusic("mc026.mp3");
Return;

scripts.杀手死亡.txt:
	Add($NpcCount,-1);
	If ($NpcCount == 0) @killed;
	Return;
	
@killed:
	StopMusic();
	Say("杨影枫：快去看看麻袋里面是不是蔷薇吧！",2);
	FadeOut();
	PlayMusic("mc013.mp3");
	DelNpc("麻袋");
	SetPlayerPos(47,38);
	SetPlayerDir(7);
	NpcSpecialAction("杨影枫","mpc241.asf");
	FadeIn();
	Sleep(2000);
	SetNpcActionFile("杨影枫", 0, "mpc241-1.asf");
	SetNpcActionFile("杨影枫", 1, "mpc241-1.asf");
	Sleep(2000);
	Say("杨影枫：蔷薇！？",4);
	Say("蔷薇：（痛哭）杨大哥！……",32);
	Say("杨影枫：到底是怎么回事？你快告诉我。",4);
	Say("蔷薇：（抽泣）杨大哥……自从你那天离开落叶谷……我就一直盼着你回来……那天……我一个人去天池玩，没想到遇到一群蒙面人……",32);
	Say("杨影枫：又是飞龙堡的人，他们为什么要绑架你呢？",4);
	Say("蔷薇：（抽泣）杨大哥……要不是你救了我，我就再见不到你了……",32);
	Say("杨影枫：蔷薇，先别哭了，你失踪了这么久，你爹一定很着急，我送你回落叶谷吧。",2);
	Say("蔷薇：（抽泣）杨大哥……回去了以后，你向我爹求亲吧，好吗？",30);
	Say("杨影枫：……蔷薇姑娘……我们先回去再说吧。",2);
	FadeOut();
	SetNpcActionFile("杨影枫", 0, "npc007_st2.asf");
	SetNpcActionFile("杨影枫", 1, "npc007_st2.asf");
	AddNpc("蔷薇.ini",48,38,3);
	SetNpcKind("蔷薇",3);
	SetNpcScript("蔷薇","蔷薇对话.txt");
	FadeIn();
	
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	Assign($Event, 1803);
	Return;

scripts.蔷薇对话.txt:
	If ($Event == 1803) @1803;
	Return;
	
@1803:
	Add($qiangwei,1);
	If ($qiangwei == 1) @qiangwei1;
	If ($qiangwei == 2) @qiangwei2;
	If ($qiangwei == 3) @qiangwei3;
	If ($qiangwei == 4) @qiangwei4;
	If ($qiangwei == 5) @qiangwei5;
	
@qiangwei1:
	Say("蔷薇：杨大哥，谢谢你救了我。",29);
	Say("杨影枫：不用谢，应该的。",2);
	Return;

@qiangwei2:
	Say("蔷薇：杨大哥，你会向我爹求亲吗？",29);
	Say("杨影枫：我不能这么做……",2);
	Say("蔷薇：杨大哥，你是不是已经有心上人了？",29);
	Say("杨影枫：我……",5);
	Return;
	
@qiangwei3:
	Say("蔷薇：杨大哥，她叫什么名字？",29);
	Say("杨影枫：纳兰真……",2);
	Say("蔷薇：杨大哥，她长得很好看吗？",29);
	Say("杨影枫：很美……", 2);
	Return;

@qiangwei4:
	Say("蔷薇：杨大哥，你觉得我好看吗？",29);
	Say("杨影枫：很好看……",2);
	Say("蔷薇：杨大哥，那我和纳兰姑娘相比谁更好看呢？",29);
	Say("杨影枫：都很美……",2);
	Return;

@qiangwei5:
	Say("蔷薇：杨大哥，纳兰姑娘现在在哪里呢？",29);
	Say("杨影枫：不知道，我也在找她。",5);
	Assign($qiangwei,0);
	Return;

scripts.路遇紫轩.txt:
	If ($Event == 1800) @1800;//结局2
	Return;
	
@1800:
	StopMusic();
	PlayMusic("mc006.mp3");
	DisableNpcAI();
	NpcGotoEx("紫轩",7,18);
	PlayerGoto(6,18);
	Say("杨影枫：紫轩！你怎么会在这里？",4);
	Say("紫轩：杨大哥……你是来找一位纳兰姑娘的吗？",16);
	Say("杨影枫：不错！你是怎么知道的？",4);
	Say("紫轩：杨大哥……纳兰姑娘可能被飞龙堡的人抓去了。",16);
	Say("杨影枫：你如何得知此事？",4);
	Say("紫轩：那日杨大哥弃我而去，我本想一死了之，却被飞龙堡的少堡主月眉儿姑娘救起，并把我带回了飞龙堡……",16);
	Say("杨影枫：紫轩……你怎么能……",4);
	Say("紫轩：后来经过月姑娘的开导，我放弃了求死的念头，但也不想长留于飞龙堡……于是准备回往芭蕉小筑……",16);
	Say("紫轩：就在早时经过一片树林时，遇到了十几个黑衣蒙面人胁持一个姑娘，在和他们的对话中我得知那个姑娘复姓纳兰，而且她还提及了杨大哥的名字。",16);
	Say("紫轩：我想这位纳兰姑娘和杨大哥必定有密切的关系，于是出手相救，怎奈他们人多势众，而且个个身手不俗，我没有救下纳兰姑娘，但从他们的打扮装束来看很像飞龙堡的人。",16);
	Say("杨影枫：飞龙堡的人为什么要绑架真儿呢？难道月眉儿她……",4);
	Say("紫轩：我也不太清楚，不过月姑娘看来到不像是个坏人。",16);

	Choose("是否相信紫轩所言？","A、相信","B、不信",$wangwei);
	If ($wangwei == 1) @no1;
	Say("杨影枫：如此多谢相告，但不知你今后有何打算……",2);
	Say("紫轩：大哥不必为我费心了，我准备回芭蕉小筑隐居，从此再不离开半步。",17);
	Say("杨影枫：紫轩……其实我……",7);
	Say("紫轩：杨大哥……我知道我以前犯的错是无法原谅的，你不必……",17);

	Choose("是否原谅紫轩？","A、原谅","B、不原谅",$wangwei);
	If ($wangwei == 1) @no2;
	Say("杨影枫：紫轩……以前的事就让它过去吧。",2);
	Say("紫轩：杨大哥……你真的肯原谅我了？",16);
	Say("杨影枫：紫轩……我其实还是喜欢你的……但是我不能对不起真儿……",7);
	Say("紫轩：杨大哥……我知道了，你快去救纳兰姑娘吧，不要管我了。",16);
	Say("杨影枫：紫轩……你多保重……",2);
	Say("紫轩：杨大哥……飞龙堡守卫森严，高手众多，你要多加小心呀。",16);
	Say("杨影枫：我会的……",2);
	Say("紫轩：再见……杨大哥……",17);
	Goto @end;
		
@no1:
	Say("杨影枫：哼……你是不是又在骗我？",6);
	Say("紫轩：杨大哥……以前是我对不起你……但是现在……",19);
	Say("杨影枫：不必你费心了，此事我自会查个水落石出的。",6);
	Say("紫轩：杨大哥……你真的如此的恨我？",19);
	Say("杨影枫：你走吧，我不想再见到你。",6);
	Say("紫轩：再见……杨大哥……",19);
	NpcGoto("紫轩",3,18);
	Watch("紫轩","杨影枫",1);
	Sleep(2000);
	NpcGoto("紫轩",0,18);
	DelNpc("紫轩");
	Say("杨影枫：真儿真的被飞龙堡抓了吗？不行，我还是去飞龙堡走一趟吧。",6);
	Memo("去飞龙堡救纳兰真");
	EnableNpcAI();
	Assign($Event, 1801);
	StopMusic();
	PlayMusic("mc014.mp3");
	Return;
	
@no2:
	Say("杨影枫：……不错……我对以前的事还无法释怀……",7);
	Say("紫轩：杨大哥……我会在芭蕉小筑一直等，希望能等到你原谅我的那一天。",17);
	Say("杨影枫：紫轩……对不起……现在我生命中最重要的是真儿。",2);
	Say("紫轩：再见……杨大哥……祝你和真儿姑娘早日团聚……",17);
	Goto @end;
	
@end:
	NpcGoto("紫轩",3,18);
	Watch("紫轩","杨影枫",0);
	Sleep(2000);
	NpcGoto("紫轩",0,18);
	DelNpc("紫轩");
	EnableNpcAI();
	Memo("去飞龙堡救纳兰真");
	Assign($Event, 1801);
	StopMusic();
	PlayMusic("mc014.mp3");
	Return;

